package day8;

public class _99_이스케이프 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println("\"안녕하세요\"");
		System.out.println("\\안녕하세요\\");
		// \n (줄바꿈), \t(탭만큼 여백)
		System.out.println("안녕\n하세요");
		System.out.println("안녕\t하세요");
	}

}
